/* Shared-site adapter for independently built application navigation.
 * Only touches navigation links, never model state, inputs, or app controls.
 */
(function () {
  function sync() {
    document.querySelectorAll('a[href="/#tools"], a[href="https://suarezcfi.com/#tools"]').forEach(function (a) { a.setAttribute('href', '/tools/'); });
    document.querySelectorAll('nav a[href]').forEach(function (a) {
      if (/\/blog\/$/.test(a.getAttribute('href')) && a.textContent.trim() === 'Journal') a.textContent = 'Blog';
    });
    // app-tool-links: generated by scripts/sync-site-metadata.py
    var items = [{"path":"/tools/","label":"All pilot tools","summary":"Explore the full collection"},{"path":"/simply-endorsed-cfi/","label":"Simply Endorsed CFI","summary":"FAA endorsement lookup"},{"path":"/part-61-calculator/","label":"CertPath","summary":"FAA rating planner"},{"path":"/flight-risk-assessment/","label":"FlightRisk","summary":"PAVE risk assessment"},{"path":"/aero-lab/","label":"Aero Lab","summary":"Interactive wind tunnel"},{"path":"/engine-explorer/","label":"Crank & Core","summary":"3D engines & flight instruments"},{"path":"/foi-cards/","label":"FOI Cards","summary":"Fundamentals of Instructing flashcards"},{"path":"/pilotsolve/","label":"PilotSolve","summary":"Mobile flight calculator"}];
    // /app-tool-links
    document.querySelectorAll('.site-navigation__drop-panel, .nav-drop-panel').forEach(function (menu) {
      items.forEach(function (item) {
        var existing = Array.from(menu.querySelectorAll('a')).some(function (a) {
          try { return new URL(a.getAttribute('href'), location.href).pathname === item.path; } catch (_) { return false; }
        });
        if (existing) return;
        var a = document.createElement('a'); a.href = item.path;
        var title = document.createElement('strong'); title.textContent = item.label; a.appendChild(title);
        var detail = document.createElement('span'); detail.textContent = item.summary; a.appendChild(detail);
        menu.appendChild(a);
      });
    });
  }
  sync();
  var root=document.getElementById('root');
  if (root) {
    var observer;
    function attach() {
      var nav=root.querySelector('nav');
      if (!nav) return false;
      if (observer) observer.disconnect();
      sync();
      new MutationObserver(sync).observe(nav,{childList:true,subtree:true});
      return true;
    }
    if (!attach()) {observer=new MutationObserver(attach);observer.observe(root,{childList:true,subtree:true});}
  }
})();
